scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch;
scwin.fr_SecuGrpId; //증권그룹ID
scwin.fr_IsurCd;
scwin.fr_SearchType; // 예비심사종목을 조회할지, 신규상장종목을 조회할지의 구분값
scwin.fr_mktTpCd; // 유가종목, 코스닥종목, 유가+코스닥전체종목 조회구분값 
scwin.vScrenID = "ULDSTF05107.xml";

scwin.onpageload = function() {
    scwin.init();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = async function() {
    const sbmOptions = {
        id: "sbm_select_list_kindstk",
        action: "/api/listing/common/pop/isu/select-list-kindstk?isurCd="+scwin.fr_IsurCd+"&isuNm="+txb_Search.getValue(),
        method: "get",
        //ref: "dlt_listKindstkReq",
        target: "dlt_listKindstkRes=body",
        isProcessMsg: false
    };
    let res = await $c.sbm.executeDynamic(sbmOptions);

    // if (!$c.util.isEmpty(res.responseJSON.errors)) {
    //     $c.win.alert(res.responseJSON.errors);
    // } else {
    txb_TotCnt.setValue(dlt_listKindstkRes.getRowCount());

    // 초기1회 초기값으로 설정된 회사코드를 검색한다.
    if (scwin.strCdSch != "") {
        for (var i = 1; i <= dlt_listKindstkRes.getRowCount(); i++) {
            if (scwin.strCdSch == dlt_listKindstkRes.getCellData(i, 1)) {
                dlt_listKindstkRes.setRowPosition(i, 0);
                break;
            }
        }
        scwin.strCdSch = "";
    }
    //}
};
scwin.txb_Search_onkeydown = function(e) {
    if (e.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
