}; */
scwin.grd_IsuInst_OnDblClick = async function(row, colid) {
    // var arrPar = new Array();
    // if (scwin.fn_SetPar != undefined) {
    //     arrPar[0] = {
    //         ISU_CD: dlt_listKindstkRes.getCellData(row, "isuCd"),
    //         ISU_NM: dlt_listKindstkRes.getCellData(row, "isuNm"),
    //         ISU_ENG_NM: dlt_listKindstkRes.getCellData(row, "isuEngNm"),
    //         ISUR_CD: dlt_listKindstkRes.getCellData(row, "isurCd"),
    //         BZPROCSNO: dlt_listKindstkRes.getCellData(row, "bzProcsNo"), //신규상장에서 사용할값.	
    //         DBCLICKYN: "Y"
    //     };
    //     scwin.fn_SetPar();
    // }
    const result = {
        ISU_CD: dlt_listKindstkRes.getCellData(row, "isuCd"),
            ISU_NM: dlt_listKindstkRes.getCellData(row, "isuNm"),
            ISU_ENG_NM: dlt_listKindstkRes.getCellData(row, "isuEngNm"),
            ISUR_CD: dlt_listKindstkRes.getCellData(row, "isurCd"),
            BZPROCSNO: dlt_listKindstkRes.getCellData(row, "bzProcsNo"), //신규상장에서 사용할값.	
            DBCLICKYN: "Y"
    }
    await $c.win.closePopup(result);
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Close_onclick = async function() {
    await $c.win.closePopup();
};
scwin.init = function() {
    window.document.body.scroll = "no";
    var arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    let parentWin = $c.win.getParent();
    var obj = parentWin.ibx_isurCd ? parentWin.ibx_isurCd : parentWin.txb_ISU_CD;   //compID가 달라서 설정

    if (obj != undefined) {
        scwin.fr_IsurCd = obj.getValue();
    } else {
        tr_Isur_Cd = "";
    }
    //scwin.fn_GetPar = parentWin.scwin.fn_GetParForIsuCd;
    //scwin.fn_SetPar = parentWin.scwin.fn_SetParForIsuCd;
    //alert('[fr_SearchTyp]'+fr_SearchTyp);

    // if (scwin.fn_GetPar != undefined) {
    //     scwin.fn_GetPar(arrPar);
    //     strSch = (arrPar.length >= 1 ? arrPar[0] : "");
    //     scwin.fr_SecuGrpId = (arrPar.length >= 3 ? arrPar[2] : "");
    //     scwin.fr_mktTpCd = (arrPar.length >= 4 ? arrPar[3] : "");
    //     scwin.fr_SearchType = (arrPar.length >= 5 ? arrPar[4] : "");
    // }

    let param = $c.data.getParameter();
    scwin.fr_SecuGrpId = param.secugrpId;
    scwin.fr_mktTpCd = param.mktTpCd;
    scwin.fr_SearchType = param.searchType;

    txb_Search.focus();
    scwin.fn_list_sync();
};
